-- Expand each practice reading into a fuller English lesson.
-- Titles, course names, and lesson order stay as seeded.
ALTER TABLE courseflow.demo_lesson_content
    ADD COLUMN paragraph_three TEXT,
    ADD COLUMN paragraph_four TEXT;
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Digital marketing starts by naming who you want to help and what action you want them to take. A large number of views does not help if those people are not the audience for the offer. This lesson, Audience and Marketing Goals, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Connect an audience to a measurable marketing goal. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Pick one group, describe the problem they have, and set a goal you can count in a set period. Separate awareness, such as seeing a post, from a later action such as signing up. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Audience and Marketing Goals in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the audience, the behavior you want, and one metric for a free lesson. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Audience and Marketing Goals, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A beginner programming course might target people who want to build a first website. A trial goal is how many of them open a free lesson, not how many people follow the brand. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write the audience, the behavior you want, and one metric for a free lesson. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Audience: beginners who have never written code. Behavior: read the lesson and try the exercise. Metric: the share of readers who finish the exercise in seven days. A strong answer stays on Audience and Marketing Goals, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Digital Marketing Basics' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'People who have just heard of a course need different information from people who are comparing options. A channel should answer the question they have at that stage. This lesson, Customer Journey and Channels, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Choose a channel that fits the stage of the customer journey. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Map awareness, consideration, action, and return. Pair each stage with one message and one channel, and keep the facts consistent when someone moves between them. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Customer Journey and Channels in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Match a channel and a message to three stages before someone enrolls. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Customer Journey and Channels, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A short sample lesson builds awareness, the course page supports comparison, and the confirmation email helps the learner start. All three should describe the same offer. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Match a channel and a message to three stages before someone enrolls. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Awareness: a short sample lesson. Consideration: the syllabus and prerequisites. Decision: price and enrollment terms, shown in the same words on the page and in email. A strong answer stays on Customer Journey and Channels, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Digital Marketing Basics' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A content plan connects a question the audience already has to one main message and a next step. Posting often without a purpose adds work and does not make the offer clearer. This lesson, Content Planning, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Plan content that answers a real audience question. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Collect real questions, group them, and give each piece an objective, a format, an owner, and a date to review results. Each piece should be summarizable in one sentence. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Content Planning in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft three pieces for one week and state the goal of each. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Content Planning, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'The question ''How do I start if I have never coded?'' can become a sample lesson plus a link to the prerequisites. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Draft three pieces for one week and state the goal of each. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Piece one answers a beginner worry, piece two shows a tiny finished example, and piece three explains the lesson order. Review whether people understood the message after publishing. A strong answer stays on Content Planning, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Digital Marketing Basics' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Search intent is what a person wants from a query: to learn a method, to compare options, or to find a specific thing. A useful page answers that question instead of repeating keywords. This lesson, Search Intent and Useful Pages, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Design a page that matches the intent behind a search. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Choose one main question, write headings that state the answer, and link only to related next steps. The page title and the body should promise the same thing. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Search Intent and Useful Pages in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Outline three sections for an article titled ''What do I need before learning UX?'' Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Search Intent and Useful Pages, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Someone searching ''what is a variable'' wants a definition and an example. A page that only lists prices does not answer them, even if the word variable appears many times. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Outline three sections for an article titled ''What do I need before learning UX?'' Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'What UX is, which basic skills it uses, and a first exercise. Each section answers the question with an example and does not claim a search ranking. A strong answer stays on Search Intent and Useful Pages, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Digital Marketing Basics' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Click-through rate is clicks divided by impressions. A signup rate must say what the denominator is, such as visitors or clicks. Rates with different denominators cannot be compared directly. This lesson, Campaign Measurement, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Calculate basic campaign rates and interpret them carefully. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Name each event and how it is counted before you collect data. Separate people from events, check for duplicates, and use a change in the number to ask a follow-up question rather than declare a cause. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Campaign Measurement in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: From 1,000 impressions, 40 clicks, 35 visitors, and 7 signups, calculate click-through rate and signup rate per visitor. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Campaign Measurement, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '2,000 impressions and 100 clicks is a 5% click-through rate. If 80 visitors produce 8 signups, the signup rate per visitor is 10%. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'From 1,000 impressions, 40 clicks, 35 visitors, and 7 signups, calculate click-through rate and signup rate per visitor. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Click-through rate is 40/1000 = 4%. Signup rate per visitor is 7/35 = 20%. Do not call 7/40 a visitor rate, because clicks and people are different units. A strong answer stays on Campaign Measurement, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Digital Marketing Basics' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A fair experiment changes one thing and keeps the audience and time window comparable. If you change the headline, the audience, and the season together, you cannot tell which change caused the result. This lesson, Experiment and Improve, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Plan a message experiment with the success rule written in advance. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write a hypothesis, the variable you will change, the metric, and the analysis plan before you start. Check side effects, and do not declare a winner from a tiny sample. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Experiment and Improve in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft one experiment for a course landing headline, including its limit. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Experiment and Improve, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Compare a headline about the outcome (''build your first site'') with a headline about volume (''20 lessons''), using the same offer and a similar audience, then look at both clicks and signups. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Draft one experiment for a course landing headline, including its limit. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Hypothesis: an outcome headline helps more people open the syllabus than a lesson-count headline. Measure syllabus views and signups. Decide the sample rule first, and accept that a small test may not be conclusive. A strong answer stays on Experiment and Improve, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Digital Marketing Basics' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Analysis starts from a decision and a question. A large table is not useful until you know the unit, the group, and the time window you will measure. This lesson, Questions Before Data, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Turn a vague question into an analysis question you can measure. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write one question, the metric, and the data required. State which result would change a decision, and what the data cannot answer. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Questions Before Data in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite ''What do learners like?'' as one measurable question. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Questions Before Data, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Instead of asking whether a course is good, ask what share of this month''s enrollees started lesson one within 7 days. That needs an enrollment time and a start time. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Rewrite ''What do learners like?'' as one measurable question. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Which lesson has the highest exercise-open rate in a named cohort. Opening an exercise does not prove they liked it; use comments if the decision is about preference. A strong answer stays on Questions Before Data, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'One table should have a clear grain, such as one learner or one event. Columns may be numbers, categories, timestamps, or identifiers. Mixing grains causes double counting. This lesson, Tables and Data Types, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Name what one row means and which type each column is. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write a short data dictionary with type, unit, and whether a value may be empty. Keep identifiers that can start with zero as text when you will not calculate with them. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Tables and Data Types in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: State the type and meaning of learner_id, lesson_id, and opened_at. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Tables and Data Types, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A lesson-open table can have many rows per learner, so the row count is not the number of learners. Count distinct learner ids when you need people. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'State the type and meaning of learner_id, lesson_id, and opened_at. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'learner_id and lesson_id are identifiers. opened_at is the event time, with a stated time zone. One row is one open event, not one learner. A strong answer stays on Tables and Data Types, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Cleaning data should preserve meaning. A blank is not always an error: it may mean the event has not happened yet, or that the system failed to record it. Those two meanings lead to different conclusions. This lesson, Cleaning Data, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Check duplicates, blanks, and inconsistent formats before you analyze. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Keep the original data, write the cleaning rule and the reason, and compare row counts before and after. Record what you deleted or changed so someone else can repeat it. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Cleaning Data in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Propose how to handle blank scores without replacing every blank with zero. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Cleaning Data, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Trailing spaces can make the same course name look like two categories. Two learners with the same display name should not be merged when their ids differ. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Propose how to handle blank scores without replacing every blank with zero. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Check whether blank means ''not submitted yet'' or ''the value was lost''. Report the count of blanks. Use zero only when the scoring rule says a missing submission is zero. A strong answer stays on Cleaning Data, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'The mean is the sum divided by the count. The median is the middle value after sorting. The mean moves when a few values are very high or very low, so also look at the spread and the count. This lesson, Descriptive Statistics, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Choose a mean or a median based on the shape of the data. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Check units and blanks, sort the values to spot extremes, then calculate both a center and a range. Pick the number that answers the question you actually asked. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Descriptive Statistics in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Calculate the mean and median of 2, 3, 3, 4, and 18. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Descriptive Statistics, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Study times of 10, 10, 15, 15, and 100 minutes have a mean of 30 and a median of 15. They describe different views of the same list. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Calculate the mean and median of 2, 3, 3, 4, and 18. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The sum is 30, so the mean is 6. The median is the third value, 3. The value 18 pulls the mean up, so check whether 18 is a real case or a data error. A strong answer stays on Descriptive Statistics, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A filter keeps the rows that belong in the question. An aggregation summarizes those rows by a group such as course or week. Groups of different sizes should not be averaged as if they were equal. This lesson, Filtering and Aggregation, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Filter and group rows with a denominator that matches the question. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Define the group and the time window before you count. Keep both the total and the number of items. When you combine group averages, weight them by each group''s size. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Filtering and Aggregation in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Group A has 3 people averaging 60. Group B has 7 people averaging 80. What is the combined average? Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Filtering and Aggregation, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Class A has 2 people with an average of 10. Class B has 8 people with an average of 20. The overall average is (2*10 + 8*20) / 10 = 18, not 15. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Group A has 3 people averaging 60. Group B has 7 people averaging 80. What is the combined average? Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The weighted total is 3*60 + 7*80 = 740. Divided by 10 people, the average is 74. Weight by the number of people because the groups are different sizes. A strong answer stays on Filtering and Aggregation, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A join matches rows through a shared key. A one-to-many relationship repeats the ''one'' side. An inner join keeps only matches. A left join keeps every row from the left table even when there is no match. This lesson, Joining Tables, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Join tables without accidentally multiplying rows or dropping people. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Name the key and the relationship, check that the key is unique on the side you expect, then compare row counts and unmatched keys after the join. Do not count people from rows that have been multiplied. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Joining Tables in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: You need every learner, including people who never opened a lesson. Which join do you use? Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Joining Tables, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'One learner with three lesson-open events becomes three rows after joining learners to events. Counting those rows as people overstates the headcount. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'You need every learner, including people who never opened a lesson. Which join do you use? Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Left-join events onto learners. Learners with no events keep a blank event side. Count distinct learner ids and confirm it still equals the original learner count. A strong answer stays on Joining Tables, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Exploration suggests questions. It does not prove cause and effect. An overall pattern can hide differences between groups, and an outlier can be either a real event or a recording error. This lesson, Exploring Patterns, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Inspect patterns and outliers before you state a conclusion. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Look at the distribution over time and by group, note missing periods, and compare cohorts that had the same amount of time to act. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Exploring Patterns in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: What should you check before concluding that completions fell last month? Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Exploring Patterns, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A cohort that enrolled yesterday has had less time to finish than a cohort from last month. Comparing completion rates immediately can make the newer course look worse. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'What should you check before concluding that completions fell last month? Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Check how long learners had to study, the number of new enrollments, whether event tracking changed, and the mix of courses. Then compare groups that were followed for the same length of time. A strong answer stays on Exploring Patterns, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 7' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Bar charts compare categories. Line charts show change over time. A scatter plot shows the relationship between two numbers. The chart should follow the question, not the decoration. This lesson, Choosing Charts, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Pick a chart that matches the comparison you want to make. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Label axes, units, and the time window. Bar charts usually start at zero so length stays comparable. Do not add colors that do not encode a category. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Choosing Charts in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Which charts fit ''score by course'' and ''study time versus score'', and what caution applies? Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Choosing Charts, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Compare enrollment across five courses with bars. Show weekly enrollment with a line and even time spacing. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Which charts fit ''score by course'' and ''study time versus score'', and what caution applies? Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Use bars for the score summary of each course, and show the number of learners. Use a scatter plot for time and score per person. A visible relationship does not prove that more time causes a higher score. A strong answer stays on Choosing Charts, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 8' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Two measures can move together because a third factor affects both. People who are already motivated may study longer and also score higher. Observing that pair does not prove one caused the other. This lesson, Correlation and Experiments, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Separate a correlation from a cause. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Offer an alternative explanation, check how the group was selected, and if you need to judge the effect of a change, plan a comparison with the rule written in advance. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Correlation and Experiments in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Name one confound when people who watch longer are more likely to pass. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Correlation and Experiments, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Learners who open the exercise score higher. They may also have been more prepared before the exercise existed. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Name one confound when people who watch longer are more likely to pass. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Prior knowledge or motivation can raise both watch time and the score. Check those factors, or run a comparison, before claiming that longer videos cause passing. A strong answer stays on Correlation and Experiments, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 9' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A usable conclusion answers the question, shows the evidence, and states how confident you are. A percentage without a unit, a denominator, or a time window is easy to misread even when the arithmetic is right. This lesson, Communicating Findings, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Report a finding with its calculation and its limit. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Start with the finding, then the method and the limit, then the decision the number can support. Separate an action you can take now from a hypothesis that still needs a check. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Communicating Findings in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a summary: 80 learners, 20 finished the exercise, and the reason they stopped is unknown. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Communicating Findings, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''30 of 50 learners in this cohort started within 7 days, which is 60%'' is clearer than ''starts are at 60%'' with no base. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a summary: 80 learners, 20 finished the exercise, and the reason they stopped is unknown. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'In that group and period, 20/80, or 25%, finished the exercise. The number does not explain why the others stopped. Check the drop-off point before changing the exercise difficulty. A strong answer stays on Communicating Findings, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Data Analytics Foundations' AND lesson_name = 'Lesson 10' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A leader helps the team see the result, the reason, and which decisions they can make. Assigning tasks without the goal can produce a finished checklist that still misses the outcome. This lesson, Shared Goals and Expectations, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Set a shared goal and the expectations around it. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Agree the goal, the owner, the definition of done, and when you will check progress. Ask the team to restate it and to name constraints before you lock the plan. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Shared Goals and Expectations in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the working agreement for preparing one trial course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Shared Goals and Expectations, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Replace ''make the lesson page better'' with ''a new learner can find lesson one and open it without asking'', plus how you will check that. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write the working agreement for preparing one trial course. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Name the owner, the content scope, the accuracy check, the draft date, and who gives feedback. Include how to raise a blocker before the deadline. A strong answer stays on Shared Goals and Expectations, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Leadership Essentials' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Listening means understanding what the other person means, including the context and the concern. Restating it gives them a chance to correct you. This lesson, Listening and Clear Communication, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Check what you heard before you answer or fix the problem. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Ask an open question, let them finish, and summarize without adding a motive. Ask whether they want help thinking, a decision, or only to be heard before you propose a fix. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Listening and Clear Communication in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft a reply to a teammate who says they will miss a deadline. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Listening and Clear Communication, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''There is too much work'' might mean the order is unclear or an urgent task arrived. Ask which part is stuck before telling them to manage time better. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Draft a reply to a teammate who says they will miss a deadline. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Ask which part remains and what is blocking it. Restate the constraint, then choose together whether to narrow the scope or add help. Write the new agreement down. A strong answer stays on Listening and Clear Communication, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Leadership Essentials' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Useful feedback names the situation, the behavior, and the impact. Coaching helps the other person choose a next try. A comment about personality is hard to act on. This lesson, Feedback and Coaching, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Give feedback about an observable behavior and its effect. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Use one specific event, ask for their view, and agree one change to try. Set a follow-up time. Do not end with a broad instruction such as ''communicate better''. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Feedback and Coaching in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite ''you are not responsible'' as feedback someone can check. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Feedback and Coaching, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''In yesterday''s meeting the task changed without telling the owner, so the work was done twice'' is clearer than ''you communicate badly''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Rewrite ''you are not responsible'' as feedback someone can check. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Name the missed task and deadline, the impact, and ask what got in the way. Agree when the status will be updated. Do not treat one event as a permanent trait. A strong answer stays on Feedback and Coaching, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Leadership Essentials' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Delegation is not handing off a burden. The owner needs the goal, the information, the resources, and a clear boundary for decisions they can make alone. This lesson, Delegation and Ownership, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Delegate an outcome together with the authority to decide. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Agree the result, the constraints, what they may decide, and what they must bring back. Match check-ins to the risk. Do not take the work back at the first difficulty. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Delegation and Ownership in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the decision boundary and the check points for the person testing a course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Delegation and Ownership, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Ask someone to prepare a sample lesson and let them choose the case study, but require an expert review before it is published. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write the decision boundary and the check points for the person testing a course. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'They may choose the test schedule and summarize issues. Changing the pass rule or opening the course to everyone needs a discussion. Review the plan before the test and the result after it. A strong answer stays on Delegation and Ownership, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Leadership Essentials' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Disagreement often comes from different information, goals, or constraints. Separating the issue from the person makes it possible to look for an option. This lesson, Conflict and Team Reflection, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Handle a disagreement by returning to the shared goal. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Let each side state the concern, restate the shared goal, and separate facts from assumptions. Choose a decision method or a small trial, then review how the team worked. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Conflict and Team Reflection in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write three reflection questions for the team after a trial launch. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Conflict and Team Reflection, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'One side wants to launch quickly and the other worries about errors. A small-group trial after the core lessons are checked can serve both concerns. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write three reflection questions for the team after a trial launch. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'What helped us finish; where did the work stall and why; what one change will we try next, with an owner and a date to review it. A strong answer stays on Conflict and Team Reflection, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Leadership Essentials' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Iterative delivery reduces uncertainty by shipping something people can try, then learning from the result. Splitting a calendar into sprints does not help if a sprint produces nothing you can check. This lesson, Iterative Delivery, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Deliver a small usable slice and learn from it. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Define a small result that completes one path, choose who will try it, and collect feedback before planning the next slice. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Iterative Delivery in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Split an online learning flow into three usable results. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Iterative Delivery, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A first slice that lets someone open one lesson from the list to the reading is more useful than a set of buttons with no lesson behind them. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Split an online learning flow into three usable results. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Open the first lesson, then save progress, then try an exercise and compare it with a suggested answer. Name who will try each slice and how you will judge it. A strong answer stays on Iterative Delivery, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A backlog is the set of work that might help the goal. A user story names who needs what and why. The useful detail is the conversation and the acceptance checks, not a fixed sentence template. This lesson, Backlog and User Stories, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Write backlog items as user needs with acceptance checks. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write the person, the action, and the benefit, plus examples you can use to accept the work. Split an item that is too large to check while keeping a user-visible result. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Backlog and User Stories in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a user story and two acceptance checks for a ''mark as complete'' button. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Backlog and User Stories, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A learner wants to return to an unfinished lesson without searching. A check: opening the course shows the unfinished lesson, and a course they do not own stays hidden. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a user story and two acceptance checks for a ''mark as complete'' button. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A learner wants to record a finished lesson so they can see progress. Checks: the status changes only after the server succeeds; a failed save shows an error and does not look complete. A strong answer stays on Backlog and User Stories, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Priority is not only what looks impressive. A small item that removes a blocker can matter more than a visible item that cannot start yet. This lesson, Priorities and Dependencies, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Order work by value, risk, and what must exist first. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write dependencies, name the uncertainty you should test first, and choose the shortest path that lets you check value. Avoid starting many items that all wait on the same missing piece. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Priorities and Dependencies in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Order ''prepare content'', ''build the lesson page'', and ''test with a user'', and say what can happen in parallel. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Priorities and Dependencies, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'The lesson page needs a lesson structure and content. Saving progress needs a learner and a lesson id. Agree those ids before connecting the systems. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Order ''prepare content'', ''build the lesson page'', and ''test with a user'', and say what can happen in parallel. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Agree the content shape first. Writing and the page can proceed together with a shared sample. Test the path after they connect. Do not wait for every lesson before checking the first one. A strong answer stays on Priorities and Dependencies, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'An estimate is a forecast from what you know, not a promise. Work you do not understand needs a discovery slice. Capacity must subtract support work, meetings, and helping each other. This lesson, Estimation and Capacity, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Estimate to plan, and treat the number as uncertain. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Break the work until you can compare it with something you have done, state the assumptions, and take on only what the team can likely finish. Do not add scope because the number looks tidy. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Estimation and Capacity in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: A team has 30 hours, 8 hours of support, and 4 hours of meetings. How much remains, and is it certain? Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Estimation and Capacity, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A team with 40 hours that already owes 12 hours of support has at most 28 hours to plan, before any buffer for surprises. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'A team has 30 hours, 8 hours of support, and 4 hours of meetings. How much remains, and is it certain? Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = '18 hours remain under those assumptions. It is still uncertain, so choose work that fits and name what you will drop if something interrupts. A strong answer stays on Estimation and Capacity, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A cycle needs a shared outcome, not only a list of tasks. The goal lets the team change details during the cycle and still know what matters. This lesson, Planning a Work Cycle, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Set a cycle goal the team can use to make tradeoffs. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Choose the goal, check that the items are ready and that the team has capacity, and agree what ''done'' means. An item with an unanswered question may need discovery before it enters the cycle. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Planning a Work Cycle in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a cycle goal for adding exercises, without using the task list as the goal. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Planning a Work Cycle, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'The goal ''a learner can open a lesson and save completion'' ties the page, the content, and the API together. Each part alone is not the result. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a cycle goal for adding exercises, without using the task list as the goal. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A learner can try a question after a lesson and compare it with a suggested answer. Done includes showing the question on the lesson, opening the answer, and not claiming the answer was submitted if there is no submit flow. A strong answer stays on Planning a Work Cycle, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A board shows work in progress, waiting, and done. Its purpose is to help work move, not only to watch people. A long queue often means a bottleneck. This lesson, Visualizing Work and Blockers, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Use a board to see flow and to unblock work. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Define what each column means, limit how much new work you start while older work is stuck, and name who can help with a blocker. An update should say what help is needed and the next step. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Visualizing Work and Blockers in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Suggest how to handle five items waiting on one reviewer. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Visualizing Work and Blockers, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Ten lessons are written and waiting for review. Starting ten more increases the queue. Help the review step first. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Suggest how to handle five items waiting on one reviewer. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Make the review checklist clear, order the items that unblock the main path, and share review where someone else is qualified. Pause new starts while the queue is the constraint. A strong answer stays on Visualizing Work and Blockers, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A review looks at what was delivered and what users or stakeholders learned. A retrospective looks at how the team worked. Each should end in a decision or a small change to try. This lesson, Review and Retrospective, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Separate a review of the product from a retrospective of the way you worked. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'In the review, try the working result and collect feedback. In the retrospective, use a real event, pick few changes, and name an owner and a follow-up cycle. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Review and Retrospective in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Separate ''the button is too small'' from ''review started on the last day'', and name the next step for each. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Review and Retrospective, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'The review finds that learners cannot find the suggested answer. The retrospective finds that the team did not try the screen on a phone before handing it over. Those are different facts. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Separate ''the button is too small'' from ''review started on the last day'', and name the next step for each. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The small button is product feedback: resize it and test. Late review is a process issue: try reviewing in the middle of the cycle and check whether the queue shrinks. A strong answer stays on Review and Retrospective, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 7' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Done includes the quality needed for real use, not only finished writing or finished code. Agree checks for correctness, access, failure cases, and what you are not supporting yet. This lesson, Quality and Release Readiness, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Define release readiness as checks you can perform. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Walk the main path and a failure case with realistic data. Record limits, plan how you will watch the result after release, and do not postpone a problem that blocks the main path without a plan. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Quality and Release Readiness in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write four readiness checks for a practice course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Quality and Release Readiness, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A course is ready for a trial when each lesson opens, the text matches the title, completion saves, and a failed save tells the learner they can retry. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write four readiness checks for a practice course. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The reading matches the lesson and is labeled as practice content; it is readable on a phone; an enrolled learner can open it and save progress; a missing reading or a failed request shows a clear message. A strong answer stays on Quality and Release Readiness, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Agile Project Management' AND lesson_name = 'Lesson 8' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Design thinking is a way to learn about people''s problems and test responses. It is not a single pass you finish and file. When an assumption is wrong, you go back to what you observed. This lesson, Understanding Design Thinking, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Separate the problem, the assumption, and the proposed solution. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write what you know and the evidence, separate what you are still guessing, and pick the riskiest guess to check. A clear problem reduces the chance of building something nobody needs. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Understanding Design Thinking in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Split ''the library needs a new app'' into a problem, an assumption, and a proposal. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Understanding Design Thinking, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'People may skip a library because the hours clash with work. A booking app does not help if the constraint is the opening time. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Split ''the library needs a new app'' into a problem, an assumption, and a proposal. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The proposal is a new app. The assumption is that an app would increase use. The problem still needs evidence, such as students being unable to get a seat at the time they can study. A strong answer stays on Understanding Design Thinking, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Understanding a user means watching what they do and the context around it. The same action can have several causes, so record the event before you interpret it. This lesson, Empathy and Observation, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Observe a situation before you assign a motive. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Pick one activity, ask permission to observe, note the sequence and where they pause, then ask a neutral question. Do not record private details you do not need. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Empathy and Observation in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write what you observed, and one follow-up question, when someone returns to the price three times. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Empathy and Observation, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A pause on a payment screen may mean the person is finding a card, not that they misunderstand the screen. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write what you observed, and one follow-up question, when someone returns to the price three times. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'You saw them open the price three times. Ask what they were checking. Do not write that the price felt too high until they say so. A strong answer stays on Empathy and Observation, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A useful problem statement has a specific user, a need, and a reason grounded in evidence. If it is too broad, the team cannot tell whether a test worked. If it is already a feature, it closes off other options. This lesson, Defining the Problem, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Write a problem statement that names the person, the need, and the reason. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Cluster similar observations and write: this group needs to do something because of something you observed. Mark which parts are evidence and which are still assumptions. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Defining the Problem in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a problem statement for learners who open a course and do not know which lesson to start. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Defining the Problem, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''Students who work in the evening need a place to read late because the library closes during their shift'' is clearer than ''build a library app''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a problem statement for learners who open a course and do not know which lesson to start. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'New learners need to see a starting point and the lesson order because they do not yet know which basics each lesson assumes. Check that this happens for that group, not for every learner. A strong answer stays on Defining the Problem, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Ideation is for expanding options. Evaluation comes after. Choosing the first idea can hide a process or a message change that would work without new software. This lesson, Generating Ideas, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Generate several options before you choose one. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Give everyone the same problem, write quietly first, then share and group related ideas. Use criteria you agreed in advance to pick what to test. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Generating Ideas in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Propose three ways to reduce confusion at the start of a course. At least one must not require new software. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Generating Ideas, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Not knowing where to start might be addressed by a one-page study plan, labels on foundation lessons, or a short placement check. It does not have to begin as an automated recommender. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Propose three ways to reduce confusion at the start of a course. At least one must not require new software. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A one-page start guide, labels on foundation lessons, and a short placement check. Compare how well a new learner understands the path and how much effort each option takes to maintain. A strong answer stays on Generating Ideas, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'An idea contains several assumptions: whether people want it, whether you can build it, and whether you can support it. Test the one that stops the idea if it fails. This lesson, Choosing Experiments, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Test the assumption that would sink the idea if it is wrong. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write the assumption as a sentence you can check, and define the evidence and the decision rule before the test. Do not change the rule afterward to make the result look better. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Choosing Experiments in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: State an assumption and what you will observe for a weekly study plan. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Choosing Experiments, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Before building a classmate-matching system, match a small group by hand and see whether people actually meet. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'State an assumption and what you will observe for a weekly study plan. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Assumption: learners can schedule study time when they see the week''s work. Observe whether they build a plan without help, and whether they follow it. A strong answer stays on Choosing Experiments, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A low-cost prototype lets you change direction quickly. It only needs enough detail for someone to understand the situation you are testing. This lesson, Building Low-Cost Prototypes, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Shrink a prototype until it answers one question. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Pick one path, sketch the information and controls that path needs, prepare the response to a click, and tell the participant what the prototype cannot do without teaching them the answer. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Building Low-Cost Prototypes in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Say what a prototype for choosing a lesson must include, and what it can leave out. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Building Low-Cost Prototypes, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Three paper screens, list, lesson, and summary, can test whether someone can find the next lesson. You do not need video or payments for that question. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Say what a prototype for choosing a lesson must include, and what it can leave out. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Include lesson names, order, and a continue control. Leave out checkout and real video if the question is whether the person understands the sequence. A strong answer stays on Building Low-Cost Prototypes, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A test produces behavior and comments. Praise does not mean the task succeeded. Check whether people could do the thing you intended. This lesson, Testing and Iteration, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Use a test result to change the idea, including evidence that is not praise. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write what you expected, what happened, and what you will change. Fix the blocker on the main task first, then test again with a comparable task. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Testing and Iteration in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Three of three people cannot find where to start, and they like the color. What do you change, and how do you check it? Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Testing and Iteration, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'If someone says the page looks nice but cannot find Start, fix the order of information and the button before adding decoration. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Three of three people cannot find where to start, and they like the color. What do you change, and how do you check it? Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Make the start of lesson one obvious, then test whether a new learner begins without help. Do not use compliments about color as the measure for this problem. A strong answer stays on Testing and Iteration, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 7' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A design story connects the context, the problem, the evidence, the approach, and the test result. The audience should see why you chose the direction and what you still do not know. This lesson, Presenting a Design Story, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Present a design decision with the evidence behind it. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Use enough evidence to be checked, show what changed after the test, and end with a next step. Do not treat a small group as all users. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Presenting a Design Story in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Outline five parts of a presentation about helping learners start lesson one. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Presenting a Design Story, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Show where people got stuck in the first prototype, the screen you changed, and what they did in the next test, including how many people you watched. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Outline five parts of a presentation about helping learners start lesson one. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Context, the problem you observed, the approach you tested, the result and its limit, and the next step. Tie each recommendation to evidence instead of showing screens alone. A strong answer stays on Presenting a Design Story, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Design Thinking Fundamentals' AND lesson_name = 'Lesson 8' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A research question is what the team needs to learn. An interview question is what you ask a participant. They do not have to use the same words. A good plan starts from the decision the result will support. This lesson, Research Questions and Planning, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Write a research question that can inform a decision. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Name the uncertainty, the user group, the method, and the output. Use interviews to understand reasons and observation to see the work itself. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Research Questions and Planning in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a research question and a method for learners who stop in the middle of a course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Research Questions and Planning, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'The team must decide where to change signup. The research question is where people get stuck. The interview question is to walk through the last time they signed up. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a research question and a method for learners who stop in the middle of a course. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Ask which factors and contexts led them to stop. Interview people who stopped recently and, with permission, look at their learning events. Do not infer the reason from click counts alone. A strong answer stays on Research Questions and Planning, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Participants should have experience that is relevant to the question. Recruiting only people nearby narrows the view. Recruiting a varied group that never faced the task does not answer it either. This lesson, Recruiting Participants, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Recruit people whose recent behavior matches the question. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write inclusion and exclusion criteria, screen for behavior, explain the purpose and how you will use the data, and let people decline or stop. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Recruiting Participants in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write two screening criteria for a study of finding a course on a phone. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Recruiting Participants, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A study of a first course purchase should include people who recently bought a first course, not only regular learners who already know the screens. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write two screening criteria for a study of finding a course on a phone. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'They searched for a course on a phone in a stated period, and they can describe a learning goal. Include both people who bought and people who did not, so you do not only see the successful path. A strong answer stays on Recruiting Participants, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'An interview uses open questions and follow-ups to understand an experience. A question that already contains your explanation pushes the participant into your frame. This lesson, Interview Techniques, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Ask follow-up questions without leading the answer. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Start from a recent event, ask what happened next and how they decided, leave time to think, and restate so they can correct you. Avoid asking several topics in one sentence. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Interview Techniques in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite ''you could not find this button because the color is too light, right?'' as a neutral question. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Interview Techniques, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Instead of ''did you stop because the lesson was long?'', ask what was happening when they decided to stop and what they were trying to do. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Rewrite ''you could not find this button because the color is too light, right?'' as a neutral question. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Ask what they were looking for and where they looked. Then ask what helped or hindered, without naming the cause for them. A strong answer stays on Interview Techniques, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Watching someone in context shows tools, constraints, and workarounds they may not describe. The environment and interruptions can matter more than the screen. This lesson, Contextual Observation, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Record what happened separately from what you think it means. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write time, actions, and quotes in an evidence column. Keep interpretation in another column. Ask a confirming question after a natural pause so you do not break the task. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Contextual Observation in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Make a two-column note for someone who switches to a banking app and then returns to checkout. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Contextual Observation, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A learner who pauses a video every two minutes to write in a notebook may be studying on purpose, not showing boredom. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Make a two-column note for someone who switches to a banking app and then returns to checkout. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Evidence: they switched to the banking app and came back. Interpretation: they may have been checking a balance. Ask them. Do not record a failed payment unless you saw that result. A strong answer stays on Contextual Observation, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A survey collects answers in a consistent form. Quality depends on the questions and on who responds. A question that asks two things at once does not tell you which thing the score reflects. This lesson, Survey Design, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Write survey questions that respondents will interpret the same way. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Use a clear time window and words, separate each topic, make options cover the possibilities without overlap, and try the survey with a few people first. Report who answered and who did not. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Survey Design in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Revise ''how often do you study?'' so the answers mean the same thing to everyone. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Survey Design, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Split ''was the lesson fun and easy to understand?'' into interest and comprehension. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Revise ''how often do you study?'' so the answers mean the same thing to everyone. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'In the last 7 days, on how many days did you open a lesson: 0, 1-2, 3-4, or 5-7. The ranges do not overlap and the unit is days. Check whether you needed opens or completed lessons. A strong answer stays on Survey Design, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Synthesis turns scattered notes into a pattern the team can use. A theme should describe what the evidence shares, not a vague bucket such as ''user problems''. This lesson, Synthesis and Themes, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Group findings into themes that still point back to evidence. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Break notes into observations, group them by meaning, name the theme, and keep a link to the evidence. Also keep the cases that do not fit, so differences stay visible. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Synthesis and Themes in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Build a theme from three notes: people search for Start, ask whether lessons are in order, and do not know the prerequisites. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Synthesis and Themes, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''I do not know if I paid'' and ''I am still waiting for the email'' may both be a theme about missing confirmation after payment, if you check they are the same moment. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Build a theme from three notes: people search for Start, ask whether lessons are in order, and do not know the prerequisites. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A possible theme is ''the starting path is not visible''. Keep the evidence about the button, the order, and the prerequisites separate so you do not treat them as one fix. A strong answer stays on Synthesis and Themes, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A research report separates what you saw, how you interpret it, and what you recommend. A small group can reveal a problem. It should not be written as a percentage of all users unless the sample supports that. This lesson, Research Reporting, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Report findings with the sample and the limit. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Start with the question and who you studied, summarize the main points with evidence, state the limit, and propose a decision or a follow-up study the result can support. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Research Reporting in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft one finding from a test of 5 people in which 3 did not realize signup had succeeded. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Research Reporting, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''4 of 5 participants in this round could not find the receipt'' is different from ''80% of all customers cannot find the receipt''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Draft one finding from a test of 5 people in which 3 did not realize signup had succeeded. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'In this round, 3 of 5 people did not find confirmation after signup. Attach what they did or said, suggest a clearer confirmation, and state that you do not yet know how often this happens for all users. A strong answer stays on Research Reporting, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX Research Methods' AND lesson_name = 'Lesson 7' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A product vision describes the future you want to create for someone and why. It is not a list of every feature. A clear direction helps you accept work that supports the goal and pause work that does not. This lesson, Product Vision, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Write a product direction that names the user problem it serves. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Name the audience, the main problem, and the long-term result. Try using the sentence to accept or reject a sample feature. If it cannot decide, it is still too broad. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Product Vision in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a vision for an app that helps beginners practice programming. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Product Vision, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''Help working adults start a new skill with lessons they can finish in a limited time'' is a clearer direction than ''build the best platform''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a vision for an app that helps beginners practice programming. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Help beginners build a small working program through short practice steps. Use that sentence to ask whether a new idea actually helps them produce something, or only adds a feature. A strong answer stays on Product Vision, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'People of the same age can need different outcomes. A strategy segment should reflect the goal, the constraint, and the behavior that changes which product fits. This lesson, Customer Segments, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Segment people by the job they are trying to do, not only by a demographic. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Collect patterns of need, choose a starting segment the team can reach, and write what you will not support yet. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Customer Segments in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Describe two learner segments by goal, and one need that differs between them. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Customer Segments, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Career-switchers may need projects and feedback. People fixing a task at work may need a short answer they can find quickly. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Describe two learner segments by goal, and one need that differs between them. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Career change: a practice path and a portfolio piece. A specific work task: a short lesson that is easy to search. Check this split against real enrollments before you build for it. A strong answer stays on Customer Segments, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'An opportunity is a problem that matters and is still poorly served. Look at frequency, severity, current alternatives, and what your team can actually do. This lesson, Problem and Opportunity, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Judge an opportunity separately from how large the idea sounds. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write the problem with evidence, how people cope today and what that costs, and which part of the opportunity size you still have to estimate. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Problem and Opportunity in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Name three facts you still need before building a new homework system. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Problem and Opportunity, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Learners submitting work through several channels and then losing the feedback may be an opportunity to keep one history. First check how often it happens and for whom. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Name three facts you still need before building a new homework system. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'How often work is lost, the impact on learners and instructors, and the current workaround, including the cost of switching. Interest alone is not enough. A strong answer stays on Problem and Opportunity, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A value proposition connects a group''s problem to the result your product helps them get. Features are how you deliver value. More features do not automatically mean more help. This lesson, Value Proposition, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: State value as an outcome for a specific person, not as a feature list. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write for whom, what problem, how you help, and which alternative you are different from. Mark claims you can support and claims you still need to test. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Value Proposition in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Rewrite ''100 video clips'' as a value statement you would still need to test. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Value Proposition, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''Keep the instructor''s comments on each piece of work so the next revision is easier'' describes a result more clearly than ''a new dashboard''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Rewrite ''100 video clips'' as a value statement you would still need to test. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Help beginners practice until they can build a first web page, using lessons in a set order. Test whether learners actually finish that page. The clip count is not evidence of the outcome. A strong answer stays on Value Proposition, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Competitors are not only similar products. People may use a spreadsheet, ask a friend, or do nothing. Positioning should explain why changing is worth it. This lesson, Positioning and Alternatives, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Compare your offer with the alternatives people already use. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Choose criteria from the user''s job, compare real alternatives, and include a tradeoff of your own product. Do not pick only the criteria on which you win. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Positioning and Alternatives in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Compare an online course and an article on two criteria. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Positioning and Alternatives, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A course with feedback may fit someone who wants work reviewed. A free article may fit someone who wants a short answer immediately. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Compare an online course and an article on two criteria. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Structure of the learning path, and whether the learner gets feedback. Some articles are structured, and some courses have no reviewer. Look at the specific options before you conclude. A strong answer stays on Positioning and Alternatives, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Output is what the team delivers, such as a number of lessons. An outcome is the change you want, such as a learner completing an exercise on their own. Usage numbers need the goal as context. This lesson, Outcomes and Metrics, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Separate an output you shipped from an outcome for the user. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Pick one outcome, a metric, how you count it, and the time window. Add a guardrail metric for a side effect, such as confusion or refunds. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Outcomes and Metrics in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Choose a primary metric and a guardrail for shortening lessons. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Outcomes and Metrics, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Adding 10 lessons is an output. The share of learners who pass a project against a written rubric is closer to an outcome, if the group and the rubric are defined. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Choose a primary metric and a guardrail for shortening lessons. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Primary: the share of learners who finish the exercise after the lesson. Guardrail: requests for help or reports of confusion. A shorter watch time alone is not success. A strong answer stays on Outcomes and Metrics, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Prioritization spends a limited team. An interesting item may not be the most important one. Scores help the conversation only when you can say where the numbers came from. This lesson, Prioritization, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Order work with a reason and with the uncertainty attached. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Use impact, confidence, and effort. Note the source of each estimate, and handle blockers or obligations before you compare scores. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Prioritization in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Order ''video will not play'', ''add a color theme'', and ''improve lesson search'', with a reason. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Prioritization, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Fixing a lesson that will not open can outrank a new color theme, because it blocks the main job even if it looks less new. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Order ''video will not play'', ''add a color theme'', and ''improve lesson search'', with a reason. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Start with video playback if it blocks learning. Then judge search by how many people are stuck. The theme can wait without evidence that it blocks the job. Say which new evidence would change the order. A strong answer stays on Prioritization, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 7' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A roadmap connects a goal to the work you expect will reach it. Later work is usually less certain than near-term work. Showing every item as a promised date overstates what you know. This lesson, Roadmaps and Dependencies, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Show a roadmap as outcomes, and mark how certain each date is. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Use now, next, and later. Name the outcome and what you still need to learn. Include dependencies, such as content that must exist before you can test the learning path. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Roadmaps and Dependencies in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Lay out three stages for opening a new course, including one dependency. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Roadmaps and Dependencies, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Now: a learner can read a lesson. Next: try an exercise. Later: evaluate automatic feedback. Each stage has a rule for whether you continue. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Lay out three stages for opening a new course, including one dependency. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Prepare the syllabus and the readings, test the path with a small group, then open it more widely. Content and access must be checked before you can learn whether people can study. A strong answer stays on Roadmaps and Dependencies, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 8' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A strategy is a set of choices and assumptions you keep checking. A review does not mean changing direction whenever a number moves. Ask whether the accumulated evidence still supports the choice. This lesson, Strategy Review, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Review the strategy when the evidence changes, not on every small swing. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Set a review rhythm, compare results with the goal, look for other explanations, and record whether you will continue, adjust, or stop, plus what you will check next. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Strategy Review in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a review note: signups rose, and the number of finished projects stayed the same. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Strategy Review, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Many signups and few lesson starts should lead you to inspect the start step and motivation before you spend more to acquire signups. It does not by itself prove the course content is poor. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a review note: signups rose, and the number of finished projects stayed the same. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Separate the rate from the raw count. Check the cohort and how long they have had to work. Form a hypothesis about starting or about the content, and choose which evidence to collect before you expand marketing. A strong answer stays on Strategy Review, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Product Strategy' AND lesson_name = 'Lesson 9' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A service is the set of activities that help a person reach a goal, before, during, and after they use it. A touchpoint is something they encounter, such as an app, a staff member, or a receipt. Service design looks at how those pieces relate. This lesson, Introduction to Service Design, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Tell a service apart from a single touchpoint. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Start with one user group and one goal, then list what they must do. Note both what they see and the work behind the scenes. Do not start by choosing a screen, because the problem may be in the process. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Introduction to Service Design in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Choose a familiar service. Name the user''s goal and one touchpoint before, during, and after use. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Introduction to Service Design, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A cafe app can take an order quickly and still confuse people if there is no sign at the pickup point. An easy order screen is only one touchpoint. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Choose a familiar service. Name the user''s goal and one touchpoint before, during, and after use. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A cafe: the goal is to get coffee before work. Before: the menu. During: order and payment. After: pickup and a way to report a problem. The service is wider than the app. A strong answer stays on Introduction to Service Design, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Welcome to the Course';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'This course moves from what a service is, to how you study users, to principles for working across a team, and then to improving a service. Reading the lessons in order helps each idea connect to a situation you already know. This lesson, Course Overview, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Explain the path of this service design course and what you will practice. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Before you start, pick one familiar service as your case. After each lesson, return to that service and note a user, a touchpoint, or a backstage task you can see more clearly. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Course Overview in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Choose one service and write what you want to understand better by the end of the course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Course Overview, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'If you choose a cafe, the first lesson may cover ordering, and a later lesson may cover the wait and how staff coordinate. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Choose one service and write what you want to understand better by the end of the course. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Example: a cafe, and you want to know which moment makes customers wait, and what information staff use to sequence orders. A strong answer stays on Course Overview, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Course Overview';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Learners arrive with different backgrounds. Some have designed screens, and some have worked a counter or run a process. Knowing which part you already understand helps you choose examples that match real work. This lesson, Getting to Know You, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Name your own experience and the goal you bring to this course. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write a role you have had, a service you use often, and one problem you want to improve. Separate something you have actually seen from something you are guessing. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Getting to Know You in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write one piece of prior experience and one question you want this course to help you answer. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Getting to Know You, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Someone who has taken orders may notice that customers ask for status often, without yet knowing whether the issue is the wait time or an unclear message. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write one piece of prior experience and one question you want this course to help you answer. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Example: you have helped customers in a shop, and you want to learn how to explain a wait without adding work for the staff. A strong answer stays on Getting to Know You, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'Getting to Know You';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Service design looks at what the user does and what the organization must arrange so that path works. It is not limited to an interface. A good result helps the user reach a goal and lets the team deliver the service. This lesson, What is Service Design ?, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Explain service design as the user''s whole path, not one screen. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Start from the user''s goal, walk before, during, and after, and note the people and supporting systems in each stage. That often shows a process change instead of another screen. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice What is Service Design ? in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Pick one service and name two touchpoints plus one backstage task. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study What is Service Design ?, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Food delivery involves the order screen, the restaurant, the courier, and the status message. If food arrives late, the problem may be the handoff between those parties. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Pick one service and name two touchpoints plus one backstage task. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A cafe touchpoint can be the menu and the pickup counter. A backstage task is sending the order to the barista in queue order. A strong answer stays on What is Service Design ?, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 1' AND sub_lesson_name = 'What is Service Design ?';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Service design principles start from the user, look at the whole service, and include the people who deliver it. A convenient idea for the customer still has to be possible for staff and systems. This lesson, Service Design Principles, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Use the user''s view and the team''s constraints to guide a service decision. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Collect problems from customers and from operations, then write decision principles you can observe, such as ''the customer always knows the next step''. Compare options against those principles. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Service Design Principles in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write two design principles for an appointment service, and how you would tell they are being met. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Service Design Principles, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A hotel message that states when the room will be ready, and who to contact, helps the guest. Staff also need a workable way to update that time. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write two design principles for an appointment service, and how you would tell they are being met. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Always know the status: the person can see the date, time, and place. Easy to change: they can move the appointment without re-entering everything, within the provider''s real constraints. A strong answer stays on Service Design Principles, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 2' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A journey map shows the steps, actions, feelings, and problems of one user in one situation. A useful map cites an observation or a story from a real event. Do not fill in feelings you did not hear. This lesson, User Research and Journey Mapping, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Build a journey map from what users actually did. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Ask about the last time they used the service, split the story into stages, and keep quotes and problems separate from your assumptions. Mark the stuck point and what you still need to ask. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice User Research and Journey Mapping in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Make a four-step journey for enrolling in a course, and mark one problem that needs another interview. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study User Research and Journey Mapping, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A course applicant searches, compares, pays, and waits for email. The stuck point may be not knowing whether payment succeeded, rather than failing to find the pay button. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Make a four-step journey for enrolling in a course, and mark one problem that needs another interview. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Search, compare, pay, start learning. If you suspect worry after payment, ask how they checked the status the last time they paid. A strong answer stays on User Research and Journey Mapping, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 3' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A design question names who has the problem and in what situation, without locking the solution. Starting with ''how might we help this person do X'' leaves room for several approaches. This lesson, Framing and Prioritizing Opportunities, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Turn a service problem into a question you can test, then order the opportunities. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Order opportunities by impact, how strong the evidence is, and the effort required. The score is a discussion aid. Separate what you should test from what you already know well enough to build. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Framing and Prioritizing Opportunities in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write a question from ''people wait for an item and do not know how long'', and propose two different responses. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Framing and Prioritizing Opportunities, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Replace ''build a chatbot'' with ''help an applicant know the status after payment''. The response might be a status page, an email, or a line on the receipt. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write a question from ''people wait for an item and do not know how long'', and propose two different responses. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'How might we help a customer plan while they wait: show an estimated window, or notify them when they are near the front. Test whether they understand that the time is uncertain. A strong answer stays on Framing and Prioritizing Opportunities, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 4' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A service prototype can be a script, paper, or a person standing in for a system. The goal is to learn from the user''s reaction, not to finish the whole system first. This lesson, Service Prototyping, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Choose a service prototype that tests one assumption with little buildup. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write one assumption, the situation you will test, and what you will watch. Let the person try without coaching every step, then ask why and note what to change. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Service Prototyping in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Design one test of a queue notice. State the assumption, the user''s task, and what you will observe. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Service Prototyping, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Before building a queue system, a team can use paper tickets and a staff text message to see whether customers understand the time and the pickup point. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Design one test of a queue notice. State the assumption, the user''s task, and what you will observe. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Assumption: a message plus a simple map helps people collect the item at the right place. Task: read the message and go to the point. Watch whether they ask for directions. Do not treat a compliment about the wording as the result. A strong answer stays on Service Prototyping, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 5' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A service blueprint lines up the user''s actions, the visible frontstage work, the backstage work, and the supporting systems. It shows who owns each step and how one failure spreads. This lesson, Service Blueprint and Improvement, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Connect the customer''s experience to the work behind it, then pick one improvement. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Choose one journey, align frontstage and backstage work, and mark handoffs, owners, and a measure. Then choose a small improvement and watch it before you expand. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Service Blueprint and Improvement in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Sketch a short blueprint for a return, including one risk and one measure. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Service Blueprint and Improvement, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'When a customer orders coffee, the frontstage step is confirming the order, the backstage step is sending the queue to the barista, and the support is the menu and the payment status. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Sketch a short blueprint for a return, including one risk and one measure. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The customer submits a request, staff explain the steps, the warehouse checks the item, and the system refunds. A risk is that the warehouse never sends the check result. Measure the time from receiving the item to telling the customer, and name who follows up. A strong answer stays on Service Blueprint and Improvement, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Service Design Essentials' AND lesson_name = 'Lesson 6' AND sub_lesson_name = 'Sub-lesson 1';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A program is a set of instructions a computer follows to turn input into a result. Start by naming the data you have, the rule you will apply, and the result you want, before you pick a language. This lesson, Introduction to Programming, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Describe a program as input, process, and output. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Break a large job into small steps, write the steps in plain language, and try them with sample data. If a step is vague or missing a condition, fix that before you turn it into code. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Introduction to Programming in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write the steps to average three scores, and try them with 60, 75, and 90. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Introduction to Programming, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'To price notebooks: take a price of 40 and a quantity of 3, multiply 40 by 3, and show 120. The input and the result need units. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write the steps to average three scores, and try them with 60, 75, and 90. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Take the three scores, check that they are numbers, add them to 225, divide by 3, and show 75. If a value is not a number, ask for a correction before calculating. A strong answer stays on Introduction to Programming, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Software Developer' AND lesson_name = 'Introduction to Programming' AND sub_lesson_name = 'Introduction to Programming';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'An editor is where you write files. A terminal is where you run commands. Version control records the history of changes so you can repeat work, inspect a problem, and see why something changed. This lesson, Development Tools, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Tell apart the editor, the terminal, and version control. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Create a project folder and a README that says how to start. Before you save a snapshot, look at what changed. Group related changes together, and never put a password into the history. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Development Tools in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Draft a short README for an average-score program: what it does, what it accepts, and how to check the result. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Development Tools, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'When you add a price formula, review only the formula file and its example before you record the change. Leave unrelated experiments out of that snapshot. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Draft a short README for an average-score program: what it does, what it accepts, and how to check the result. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The README should say the program averages three scores, accepts only numbers, and that 60, 75, 90 produces 75. Someone else should be able to follow it and get the same result. A strong answer stays on Development Tools, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Software Developer' AND lesson_name = 'Development Tools' AND sub_lesson_name = 'Development Tools';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A variable is a name for a value. Basic types include numbers, text, and true or false. A number you will calculate is different from text that only looks numeric, such as a student id that can start with zero. This lesson, Variables and Data Types, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Choose a data type that matches the meaning of the value. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Name variables for what they mean, check the type you received, and convert on purpose. In JavaScript, adding text and a number can concatenate instead of calculate. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Variables and Data Types in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Choose types for the code ''0012'', the price 99.5, and a paid status, and say why. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Variables and Data Types, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'const price = 40 and const quantity = 3 give total = price * quantity, which is 120. The expression ''40'' + 3 produces the text ''403''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Choose types for the code ''0012'', the price 99.5, and a paid status, and say why. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The code is a string so the leading zeros stay. The price is a number so you can calculate. The paid status is a boolean such as true, not the text ''true'', if you will test it as a boolean. A strong answer stays on Variables and Data Types, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Software Developer' AND lesson_name = 'Variables and Data Types' AND sub_lesson_name = 'Variables and Data Types';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A condition chooses which instructions run. A loop repeats instructions across many items. Every condition should cover the boundary values, and every loop needs a condition that makes it stop. This lesson, Control Flow, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Use conditions and loops to handle different cases and lists. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write the rule in words first, such as a score of 50 or more passes, then test below, equal to, and above the boundary. For a loop, try an empty list and a list with several items. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Control Flow in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Design test cases for a discount that starts when the purchase is at least 1000. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Control Flow, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'if (score >= 50) treats 50 as a pass. Looping over [40, 50, 80] finds two passing scores. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Design test cases for a discount that starts when the purchase is at least 1000. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Test 999 for no discount, 1000 for a discount, and 1001 for a discount. Add a negative amount and decide that it is rejected. Do not silently change the rule to ''greater than 1000''. A strong answer stays on Control Flow, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Software Developer' AND lesson_name = 'Control Flow' AND sub_lesson_name = 'Control Flow';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A function groups the steps of one job. It takes parameters and returns a value. A module groups related code. Splitting lets you change one rule in one place. This lesson, Functions and Modules, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Split work into a function with a clear input and output. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Separate calculation from display. State the input and the output. A function that does not change outside data is easier to test, because the same input gives the same result. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Functions and Modules in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Sketch a function that averages a list of numbers, including the result for an empty list. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Functions and Modules, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'function total(price, quantity) { return price * quantity } calculates without depending on a button. total(40, 3) is 120. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Sketch a function that averages a list of numbers, including the result for an empty list. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Add the values and divide by the count. An empty list can return null, and the caller must handle that. Test [2, 4] to 3, [5] to 5, and [] to null. A strong answer stays on Functions and Modules, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Software Developer' AND lesson_name = 'Functions and Modules' AND sub_lesson_name = 'Functions and Modules';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A first project should be small enough to finish input, processing, output, and errors. A complete main path is more useful than several features that are not connected. This lesson, Build a Project, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Scope a small project and write the checks that mean it is done. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write what the user can do and the acceptance checks. Build one piece at a time, test a normal case and an invalid case, and ask someone else to follow the README without help. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Build a Project in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write three acceptance checks for a to-do app, with at least one test case each. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Build a Project, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A first to-do app can add a task, mark one complete, and delete one. One check: an empty name cannot be added, and completing task A does not change task B. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write three acceptance checks for a to-do app, with at least one test case each. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'A non-empty name appears as one item; completing A leaves B unchanged; deleting A leaves B. Also test a name that is only spaces, and say whether the list remains after a refresh. A strong answer stays on Build a Project, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'Software Developer' AND lesson_name = 'Build a Project' AND sub_lesson_name = 'Build a Project';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'UX is the experience of reaching a goal. UI is the interface a person sees and uses. A polished screen does not guarantee that someone understands the steps or can finish the task. This lesson, Design Foundations, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Separate UX from UI and put the most important information first. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Name the one job of a screen, then order the heading, the text, and the button by importance. Keep patterns consistent, and do not use color alone to show a status. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Design Foundations in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Order four pieces of information on a course signup screen and say why. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Design Foundations, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A payment screen should show the total, the items, and a clear confirm button. An error needs words, not only a red border. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Order four pieces of information on a course signup screen and say why. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'The course name and the result confirm they are on the right page. The price and terms support the decision. Supporting detail comes next. The signup button belongs where the cost is already visible. A strong answer stays on Design Foundations, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX/UI Design Beginner' AND lesson_name = 'Design Foundations' AND sub_lesson_name = 'Design Foundations';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'User research checks assumptions about a problem. A question about something that actually happened usually gives more detail than asking whether someone would use an imagined feature. This lesson, User Research, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Ask about a real recent event instead of a hypothetical opinion. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Choose people with relevant experience, ask them to tell the last time, and follow the steps and the stuck points. Keep their words separate from your interpretation. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice User Research in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write three interview questions for someone who has bought an online course. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study User Research, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Instead of ''would you like a new learning app?'', ask how they chose a course last time, what they compared, and where they stopped. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write three interview questions for someone who has bought an online course. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Where did you start the last search; what did you compare; was there a moment you nearly did not buy. Ask for the event, and do not suggest that price or the screen was the problem. A strong answer stays on User Research, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX/UI Design Beginner' AND lesson_name = 'User Research' AND sub_lesson_name = 'User Research';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A wireframe shows where information and actions go, with little visual detail. It lets you discuss structure and sequence before you invest in color or imagery. This lesson, Wireframing, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Sketch the structure of a screen from the user''s task before you decorate it. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Write the path from the start to the result, then sketch only the screens that path needs. Include empty, loading, and error states, because they are part of the experience. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Wireframing in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Sketch a wireframe of a course list, including the state when nothing matches. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Wireframing, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'Choosing a course can be a list, a detail page, and a confirmation. A search with no results needs guidance to change the query, not a blank page. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Sketch a wireframe of a course list, including the state when nothing matches. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Include a heading, a search field, and rows with a name and a price that link to detail. When nothing matches, show the query and a way to clear the filter. Do not show a signup button with no course. A strong answer stays on Wireframing, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX/UI Design Beginner' AND lesson_name = 'Wireframing' AND sub_lesson_name = 'Wireframing';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'Visual hierarchy tells someone what to read first. Size, weight, spacing, and contrast should support the role of each piece of information. Not every element should compete. This lesson, Visual Design, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Use type, spacing, and color to make the information easier to read. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Define reusable styles for headings, body text, and labels. Group related items with spacing. Check text on the real background, and pair words or an icon with color when you show a status. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Visual Design in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: A card currently uses the same text size for everything. Name three changes. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Visual Design, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'A course card can use the name as the strong heading, the description as secondary text, and the price near the signup button. A completed state needs both an icon and the words ''Completed''. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'A card currently uses the same text size for everything. Name three changes. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Give the course name more weight, reduce the emphasis of secondary details, and separate the price and the button as a group. Check that the text still fits and stays readable on a small screen. A strong answer stays on Visual Design, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX/UI Design Beginner' AND lesson_name = 'Visual Design' AND sub_lesson_name = 'Visual Design';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'An interactive prototype simulates clicks and state changes so you can test a path. It does not need a real database, but it must respond at the points the question depends on. This lesson, Interactive Prototypes, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Link screens into a prototype that can test one task. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Set the start, the goal, and the path you support. Include a way back and the result of an action. Tell the participant what the prototype cannot do, without telling them which control to press. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Interactive Prototypes in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Describe the states and the screen changes for saving a course to a wishlist. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Interactive Prototypes, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = 'If the test is choose a course, open the detail, and enroll, the same course name should stay visible along the path so they know what they are buying. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Describe the states and the screen changes for saving a course to a wishlist. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Not saved, then saved after the click, then the saved list shows that course. Pressing again should unsaved it in a consistent way. A strong answer stays on Interactive Prototypes, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX/UI Design Beginner' AND lesson_name = 'Interactive Prototypes' AND sub_lesson_name = 'Interactive Prototypes';
UPDATE courseflow.demo_lesson_content SET paragraph_one = 'A usability test asks a person to try a task while you watch. The task should state the goal without naming the button, so you can see whether they understand it themselves. This lesson, Usability Testing, is one step in the course rather than a separate topic. By the end you should be able to do this in your own words: Watch someone try a task, then order the problems you saw. Before you move on, write that outcome at the top of a note and list the two or three terms you would need to explain it to a classmate. If a sentence only sounds familiar and you cannot point to an example, stay on this section until you can.', paragraph_two = 'Note success, hesitation, and mistakes. Ask why after the moment, without blaming them. Order problems by impact and how often they appeared, then test the change. Do the work on paper or in a notes file, one decision per line. Name the person or data involved, the action you are judging, and the result you expect to see. Keep facts, such as a number, a quote, or something you observed, separate from your interpretation. When two choices both seem reasonable, write the assumption each one depends on and what evidence would make you pick one.', paragraph_three = 'Practice Usability Testing in this order. First, restate the objective without looking at this page. Second, read the example once and mark three parts: the starting situation, the rule or idea being used, and the result. Third, close the example and complete the exercise: Write one test task and three note columns for a course search page. Fourth, open the suggested answer only after you have written your own. Fifth, note one place your answer is stronger and one place the suggested answer is clearer. That comparison is the actual study, not a score.', paragraph_four = 'While you study Usability Testing, watch for three misses. Do not jump to a tool, a screen, or a formula before you can say what question the lesson is answering. Do not treat the single example as proof that the same result will happen in every case. Do not copy the suggested answer and move on; if you cannot rebuild the reasoning, repeat the exercise with a second situation from your own life or from this course. You are ready for the next lesson when your notes name who is involved, what they are trying to do, and how you would check that the idea worked.', example = '''Find a design course for someone with no background and check the price'' is a better task than ''click the Beginner filter'', because the second task gives away the method. Read that case a second time and write it as a short record: situation, idea from this lesson, and result. Then change one detail, such as the person, the number, or the constraint, and say whether the conclusion still holds. If it does not, explain which part of the lesson the new detail breaks. That extra pass is what turns an example into something you can reuse.', exercise = 'Write one test task and three note columns for a course search page. Give yourself a full answer of several sentences, not a label. Include the situation, the idea from this lesson, and the result you expect. Write it before you open the suggested answer.', solution = 'Task: find a design course for a beginner within a stated budget. Columns: whether they succeeded, what you observed, and what they said. Keep your own suggestion out of the evidence column. A strong answer stays on Usability Testing, uses evidence rather than a slogan, and could be checked by someone else. Your wording does not need to match this suggestion. It does need to cover the same decision: what you looked at, what you concluded, and what you would do or measure next. If your answer skips the check, add one sentence that says how you would know the conclusion is wrong.' WHERE course_title = 'UX/UI Design Beginner' AND lesson_name = 'Usability Testing' AND sub_lesson_name = 'Usability Testing';
ALTER TABLE courseflow.demo_lesson_content
    ALTER COLUMN paragraph_three SET NOT NULL,
    ALTER COLUMN paragraph_four SET NOT NULL;
